using System.Net;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.RegularExpressions;
namespace SysAdminAssistant.Core;
public sealed record DeviceConnections(string WebUrl="",string SshHost="",int SshPort=22,string SshUser="",string RdpHost="",int RdpPort=3389,string RdpUser="")
{
    private static readonly JsonSerializerOptions Json=new(){UnmappedMemberHandling=JsonUnmappedMemberHandling.Disallow,MaxDepth=4};
    public static DeviceConnections Parse(string json){if(string.IsNullOrEmpty(json))return new();if(json.Length>4000)throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Слишком длинные настройки подключения"));var value=JsonSerializer.Deserialize<DeviceConnections>(json,Json)??throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Пустые настройки подключения"));value.Validate();return value;}
    public string Serialize(){Validate();return JsonSerializer.Serialize(this,Json);}
    public static string Host(string value){if(string.IsNullOrEmpty(value)||value.Length>253||value.Any(c=>char.IsControl(c)||char.IsWhiteSpace(c))||value.StartsWith('-')||value.Contains('%'))throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Укажите IP или DNS-имя без URL, пути и порта"));if(IPAddress.TryParse(value.Trim('[',']'),out var ip))return ip.ToString();if(Uri.CheckHostName(value)!=UriHostNameType.Dns||value.Contains('/')||value.Contains(':')||value.Contains('@')||value.Contains('\\'))throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Неверный адрес подключения"));return value;}
    public void Validate(){if(WebUrl==null||SshHost==null||SshUser==null||RdpHost==null||RdpUser==null)throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Поля подключения не должны быть null"));if(WebUrl.Length>2000||WebUrl.Any(char.IsControl)||WebUrl.Length>0&&(!Uri.TryCreate(WebUrl,UriKind.Absolute,out var uri)||uri.Scheme is not("http" or "https")||uri.UserInfo!=""||uri.Host.Length==0))throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Web: укажите http:// или https:// без логина и пароля в URL"));if(SshPort is <1 or >65535||RdpPort is <1 or >65535)throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Порт подключения: 1–65535"));if(SshHost!="")_=Host(SshHost);if(RdpHost!="")_=Host(RdpHost);if(SshUser.Length>128||SshUser.Length>0&&!Regex.IsMatch(SshUser,@"^[\p{L}\p{N}_][\p{L}\p{N}_.@\\-]*$",RegexOptions.CultureInvariant,TimeSpan.FromMilliseconds(50)))throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("SSH: неверный логин"));if(RdpUser.Length>256||RdpUser.Any(char.IsControl))throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("RDP: неверный логин"));}
    public string[] SshArguments(){Validate();if(SshHost=="")throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("SSH не настроен"));return new[]{"-p",SshPort.ToString(System.Globalization.CultureInfo.InvariantCulture)}.Concat(SshUser==""?[]:new[]{"-l",SshUser}).Concat(new[]{"--",Host(SshHost)}).ToArray();}
    public string RdpFile(){Validate();if(RdpHost=="")throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("RDP не настроен"));var host=Host(RdpHost);if(host.Contains(':'))host="["+host+"]";return "full address:s:"+host+":"+RdpPort.ToString(System.Globalization.CultureInfo.InvariantCulture)+"\r\nprompt for credentials:i:1\r\n"+(RdpUser==""?"":"username:s:"+RdpUser+"\r\n");}
}
